// ─── Generated files viewer ───────────────────────────────────────────────────

function FilesViewerModal({ files, onClose }: {
  files:   Record<string, string>
  onClose: () => void
}) {
  const [selected, setSelected] = useState<string | null>(null)
  const [search,   setSearch]   = useState('')

  const entries = Object.entries(files)
  const reviews = reviewGeneratedSourceQuality(files)
  const reviewByFile = Object.fromEntries(reviews.map(review => [review.file, review])) as Record<string, SourceQualityReview>
  const quality = summarizeSourceQuality(reviews)
  const filtered = search
    ? entries.filter(([p]) => p.toLowerCase().includes(search.toLowerCase()))
    : entries

  // Group by directory
  const groups: Record<string, string[]> = {}
  for (const [path] of filtered) {
    const parts = path.split('/')
    const dir   = parts.length > 1 ? parts.slice(0, -1).join('/') : '(root)'
    if (!groups[dir]) groups[dir] = []
    groups[dir].push(path)
  }

  const selectedContent = selected ? (files[selected] ?? '') : ''
  const selectedReview = selected ? reviewByFile[selected] : null
  const ext = selected?.split('.').pop() ?? ''
  const isCode = ['ts', 'tsx', 'js', 'jsx', 'css', 'json', 'sql', 'md', 'sh'].includes(ext)
  const gradeClass = (grade: SourceQualityReview['grade']) =>
    grade === 'excellent' ? 'bg-emerald-500/15 text-emerald-700 border-emerald-400/30'
    : grade === 'pass' ? 'bg-lime-500/15 text-lime-700 border-lime-400/30'
    : grade === 'weak' ? 'bg-amber-500/15 text-amber-700 border-amber-400/30'
    : 'bg-red-500/15 text-red-700 border-red-400/30'

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/70 backdrop-blur-sm">
      <div className="bg-paper border border-border rounded-2xl shadow-2xl w-full max-w-5xl h-[85vh] flex flex-col overflow-hidden animate-fadein">
        {/* Header */}
        <div className="flex items-center justify-between px-5 py-3.5 border-b border-border flex-shrink-0">
          <div className="flex items-center gap-3">
            <p className="text-sm font-black text-ink">Generated Files</p>
            <span className="text-[10px] font-mono font-bold text-ink3 bg-paper2 border border-border rounded px-2 py-0.5">{entries.length} files</span>
            <span className={`text-[10px] font-mono font-black rounded px-2 py-0.5 border ${
              quality.average >= 8.5 ? 'bg-emerald-500/15 text-emerald-700 border-emerald-400/30'
              : quality.average >= 7 ? 'bg-lime-500/15 text-lime-700 border-lime-400/30'
              : quality.average >= 4 ? 'bg-amber-500/15 text-amber-700 border-amber-400/30'
              : 'bg-red-500/15 text-red-700 border-red-400/30'
            }`}>avg {quality.average.toFixed(1)}/10</span>
            {quality.critical.length > 0 && (
              <span className="text-[10px] font-mono font-bold text-red-700 bg-red-500/10 border border-red-400/30 rounded px-2 py-0.5">
                {quality.critical.length} weak critical
              </span>
            )}
          </div>
          <div className="flex items-center gap-2">
            <input
              value={search}
              onChange={e => setSearch(e.target.value)}
              placeholder="Filter files…"
              className="text-xs px-3 py-1.5 rounded-lg border border-border bg-paper2 outline-none focus:border-[#c8f23c] w-44 transition-all"
            />
            <button onClick={onClose} className="text-ink3 hover:text-ink text-xl leading-none transition-colors">✕</button>
          </div>
        </div>

        {/* Body */}
        <div className="flex flex-1 min-h-0">
          {/* File tree */}
          <div className="w-56 flex-shrink-0 border-r border-border overflow-y-auto py-2 scrollbar-thin">
            {Object.entries(groups).map(([dir, paths]) => (
              <div key={dir}>
                <p className="px-3 py-1 text-[9px] font-black font-mono tracking-widest text-ink3 uppercase sticky top-0 bg-paper">{dir}</p>
                {paths.map(p => {
                  const review = reviewByFile[p]
                  return (
                  <button
                    key={p}
                    onClick={() => setSelected(p)}
                    className={`w-full text-left px-3 py-1.5 text-[11px] font-mono transition-colors ${
                      selected === p
                        ? 'bg-[#c8f23c]/15 text-ink font-bold'
                        : 'text-ink3 hover:bg-paper2 hover:text-ink'
                    }`}
                  >
                    <span className="flex items-center gap-2 min-w-0">
                      <span className={`w-1.5 h-1.5 rounded-full flex-shrink-0 ${
                        review?.grade === 'excellent' ? 'bg-emerald-500'
                        : review?.grade === 'pass' ? 'bg-lime-500'
                        : review?.grade === 'weak' ? 'bg-amber-500'
                        : 'bg-red-500'
                      }`} />
                      <span className="truncate flex-1">{p.split('/').pop()}</span>
                      <span className="text-[9px] text-ink3 flex-shrink-0">{review?.score.toFixed(1)}</span>
                    </span>
                  </button>
                  )
                })}
              </div>
            ))}
          </div>

          {/* Content pane */}
          <div className="flex-1 min-w-0 flex flex-col">
            {selected ? (
              <>
                <div className="px-4 py-2 border-b border-border bg-paper2 flex-shrink-0 flex items-center justify-between">
                  <div className="min-w-0">
                    <p className="text-[11px] font-mono text-ink2 truncate">{selected}</p>
                    {selectedReview && (
                      <p className="text-[9px] font-mono text-ink3 mt-0.5">
                        {selectedReview.category} · {selectedContent.split('\n').length} lines
                      </p>
                    )}
                  </div>
                  {selectedReview && (
                    <span className={`text-[10px] font-mono font-black rounded px-2 py-1 border ml-2 flex-shrink-0 ${gradeClass(selectedReview.grade)}`}>
                      {selectedReview.score.toFixed(1)}/10 · {selectedReview.grade}
                    </span>
                  )}
                </div>
                {selectedReview && (
                  <div className="px-4 py-3 border-b border-border bg-paper">
                    <div className="grid gap-3 md:grid-cols-2">
                      <div>
                        <p className="text-[9px] font-black font-mono uppercase tracking-widest text-ink3">Review findings</p>
                        <ul className="mt-1 space-y-1">
                          {(selectedReview.findings.length ? selectedReview.findings : ['No deterministic quality gaps detected.']).slice(0, 4).map(item => (
                            <li key={item} className="text-[10px] text-ink2 leading-snug">• {item}</li>
                          ))}
                        </ul>
                      </div>
                      <div>
                        <p className="text-[9px] font-black font-mono uppercase tracking-widest text-ink3">Strengths</p>
                        <ul className="mt-1 space-y-1">
                          {selectedReview.strengths.slice(0, 4).map(item => (
                            <li key={item} className="text-[10px] text-ink2 leading-snug">• {item}</li>
                          ))}
                        </ul>
                      </div>
                    </div>
                  </div>
                )}
                <div className="flex-1 overflow-auto">
                  <pre className={`text-[11px] leading-relaxed p-4 min-h-full whitespace-pre-wrap break-words ${
                    isCode ? 'font-mono text-ink2' : 'font-sans text-ink3'
                  }`}>{selectedContent}</pre>
                </div>
              </>
            ) : (
              <div className="flex-1 flex items-center justify-center text-ink3">
                <div className="text-center space-y-2">
                  <p className="text-3xl">◈</p>
                  <p className="text-sm font-medium">Select a file to view its content</p>
                  <p className="text-xs text-ink3/60">{entries.length} files generated by BUILD ENGINE · avg {quality.average.toFixed(1)}/10</p>
                  {quality.critical.length > 0 && (
                    <p className="text-xs text-red-500">{quality.critical.length} critical file{quality.critical.length === 1 ? '' : 's'} need review before this is top-tier.</p>
                  )}
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  )
}

// ─── Sub-agent progress grid ──────────────────────────────────────────────────

function AgentGrid({
  agents,
  activeIds,
  doneIds,
  metaById,
  label,
}: {
  agents:    { id: string; name: string; role: string }[]
  activeIds: Set<string>
  doneIds:   Set<string>
  metaById:  Record<string, AgentRunMeta>
  label:     string
}) {
  if (activeIds.size === 0 && doneIds.size === 0) return null
  const doneCount = doneIds.size
  const total     = agents.length
  const activeAgents = agents.filter(agent => activeIds.has(agent.id))
  const nextAgent = agents.find(agent => !doneIds.has(agent.id) && !activeIds.has(agent.id))
  return (
    <div className="mt-4 space-y-4 rounded-2xl border border-white/15 bg-[#071011]/95 p-4 shadow-[0_24px_80px_rgba(0,0,0,0.28),inset_0_1px_0_rgba(255,255,255,0.06)]">
      <div className="grid gap-3 lg:grid-cols-[1fr_auto] lg:items-center">
        <div>
          <div className="flex flex-wrap items-center gap-2">
            <p className="text-[11px] font-black font-mono tracking-widest text-zinc-100 uppercase">{label}</p>
            {activeAgents.length > 0 && (
              <span className="rounded-full border border-[#c8f23c]/40 bg-[#c8f23c]/15 px-2 py-1 text-[9px] font-black font-mono uppercase tracking-widest text-[#d7ff57]">
                {activeAgents.length} live now
              </span>
            )}
          </div>
          <p className="mt-1 text-[11px] leading-relaxed text-zinc-400">
            {activeAgents.length > 0
              ? `Running: ${activeAgents.map(agent => agent.name).join(' + ')}`
              : doneCount === total
              ? 'All specialists completed and handed context to the next stage.'
              : nextAgent
              ? `Next up: ${nextAgent.name}`
              : 'Waiting for the next specialist to start.'}
          </p>
        </div>
        <div className="min-w-[180px] rounded-xl border border-white/10 bg-black/30 p-2">
          <div className="mb-1 flex items-center justify-between text-[9px] font-black font-mono uppercase tracking-widest text-zinc-400">
            <span>Progress</span>
            <span className="text-zinc-100">{doneCount}/{total}</span>
          </div>
          <div className="h-2 overflow-hidden rounded-full bg-white/10">
            <div
              className="h-full rounded-full bg-[#c8f23c] shadow-[0_0_18px_rgba(200,242,60,0.55)] transition-all duration-500"
              style={{ width: `${Math.max(5, Math.round((doneCount / total) * 100))}%` }}
            />
          </div>
        </div>
      </div>
      <div className="grid grid-cols-1 gap-3 sm:grid-cols-2 xl:grid-cols-3">
        {agents.map(a => {
          const isDone   = doneIds.has(a.id)
          const isActive = activeIds.has(a.id)
          const meta     = metaById[a.id]
          const isRestored = isDone && !meta
          const score    = meta?.score
          const wasRepaired = Boolean(meta?.replacedBySafetyNet)
          const isLowScore = isDone && !wasRepaired && score !== null && score !== undefined && score < 7
          const isCriticalLowScore = isLowScore && (a.id === 'qa' || score < 4)
          const statusLabel = isDone
            ? isRestored ? 'restored' : wasRepaired ? 'repaired' : isCriticalLowScore ? 'blocked' : isLowScore ? 'review' : 'done'
            : isActive ? 'live'
            : 'queued'
          const statusCopy = isActive
            ? 'Generating application intelligence right now'
            : isDone
            ? wasRepaired
              ? 'Recovered by deterministic safety net and ready for downstream agents'
              : isLowScore
              ? 'Needs review before it can be treated as production grade'
              : 'Completed and context is available to downstream agents'
            : 'Waiting for dependency context from earlier specialists'
          const scoreLabel = isRestored
            ? 'restored'
            : score !== null && score !== undefined
            ? `${score.toFixed(1)}/10`
            : '--'
          return (
            <div
              key={a.id}
              className={`group relative min-h-[150px] overflow-hidden rounded-xl border p-4 text-left transition-all duration-300 ${
                isActive
                  ? 'border-[#c8f23c]/80 bg-[#17240d] shadow-[0_0_36px_rgba(200,242,60,0.22),inset_0_1px_0_rgba(255,255,255,0.08)]'
                  : isCriticalLowScore
                  ? 'border-red-400/65 bg-red-500/[0.12] shadow-[0_0_28px_rgba(248,113,113,0.18)]'
                  : isLowScore
                  ? 'border-amber-400/60 bg-amber-400/[0.12]'
                  : isDone
                  ? 'border-emerald-400/35 bg-emerald-400/[0.08] shadow-[inset_0_1px_0_rgba(255,255,255,0.05)]'
                  : 'border-white/15 bg-white/[0.055]'
              }`}
            >
              <div className={`absolute left-0 top-0 h-full w-1 ${
                isActive ? 'bg-[#c8f23c]' : isCriticalLowScore ? 'bg-red-400' : isLowScore ? 'bg-amber-400' : isDone ? 'bg-emerald-400' : 'bg-white/10'
              }`} />
              {isActive && (
                <div className="absolute inset-x-0 top-0 h-px bg-gradient-to-r from-transparent via-[#c8f23c] to-transparent" />
              )}
              <div className="flex items-start justify-between gap-3">
                <div className="min-w-0">
                  <p className={`truncate text-[12px] font-black font-mono leading-tight ${
                    isActive ? 'text-[#d7ff57]' : isCriticalLowScore ? 'text-red-200' : isLowScore ? 'text-amber-200' : isDone ? 'text-emerald-200' : 'text-zinc-200'
                  }`}>{a.name}</p>
                  <p className="mt-1 line-clamp-2 text-[11px] leading-snug text-zinc-300">{a.role}</p>
                </div>
                <span className={`shrink-0 rounded-full border px-2 py-1 text-[9px] font-black font-mono uppercase tracking-wider ${
                  isActive ? 'border-[#c8f23c]/50 bg-[#c8f23c]/15 text-[#d7ff57]' :
                  isCriticalLowScore ? 'border-red-400/50 bg-red-500/15 text-red-200' :
                  isLowScore ? 'border-amber-400/50 bg-amber-400/15 text-amber-200' :
                  isDone ? 'border-emerald-400/35 bg-emerald-400/10 text-emerald-200' :
                  'border-white/15 bg-white/[0.04] text-zinc-300'
                }`}>
                  {statusLabel}
                </span>
              </div>
              <div className={`mt-3 rounded-lg border px-3 py-2 text-[10px] leading-relaxed ${
                isActive
                  ? 'border-[#c8f23c]/25 bg-black/25 text-[#e4ff8d]'
                  : isCriticalLowScore
                  ? 'border-red-400/25 bg-black/20 text-red-100'
                  : isLowScore
                  ? 'border-amber-400/25 bg-black/20 text-amber-100'
                  : isDone
                  ? 'border-emerald-400/20 bg-black/20 text-emerald-50'
                  : 'border-white/10 bg-black/20 text-zinc-300'
              }`}>
                {isActive && <span className="mr-1 inline-block h-1.5 w-1.5 rounded-full bg-[#c8f23c] align-middle animate-pulse" />}
                {statusCopy}
              </div>
              <div className="mt-3 grid grid-cols-3 gap-2 text-[9px] font-mono">
                <div className={`rounded-lg border px-2 py-1.5 ${
                  isCriticalLowScore ? 'border-red-400/35 bg-red-500/10' : isLowScore ? 'border-amber-400/35 bg-amber-400/10' : 'border-white/10 bg-black/25'
                }`}>
                  <p className="text-zinc-500">score</p>
                  <p className={`mt-0.5 font-black ${isCriticalLowScore ? 'text-red-200' : isLowScore ? 'text-amber-200' : isDone ? 'text-emerald-200' : isActive ? 'text-[#d7ff57]' : 'text-zinc-200'}`}>
                    {scoreLabel}
                  </p>
                </div>
                <div className="rounded-lg border border-white/10 bg-black/25 px-2 py-1.5">
                  <p className="text-zinc-500">tokens</p>
                  <p className="mt-0.5 font-black text-zinc-200">{meta ? meta.tokens.toLocaleString() : '--'}</p>
                </div>
                <div className="rounded-lg border border-white/10 bg-black/25 px-2 py-1.5">
                  <p className="text-zinc-500">time</p>
                  <p className="mt-0.5 font-black text-zinc-200">{meta ? formatAgentDuration(meta.durationMs) : '--'}</p>
                </div>
              </div>
              {isDone && (
                <div className="mt-2 flex flex-wrap items-center gap-1.5 text-[9px] font-mono">
                  <span className={`font-bold ${isCriticalLowScore ? 'text-red-200' : isLowScore ? 'text-amber-200' : 'text-emerald-200'}`}>
                    {statusLabel}
                  </span>
                  {meta?.repairIteration != null && (
                    <span className="rounded border border-amber-400/40 bg-amber-400/10 px-1 py-0.5 text-amber-300">
                      repair #{meta.repairIteration}
                    </span>
                  )}
                  {wasRepaired && (
                    <span className="rounded border border-emerald-400/30 bg-emerald-400/10 px-1 py-0.5 text-emerald-200">
                      safety net
                    </span>
                  )}
                  {wasRepaired && meta.originalScore != null && meta.originalScore < 7 && (
                    <span className="rounded border border-white/10 bg-black/20 px-1 py-0.5 text-zinc-400">
                      raw {meta.originalScore.toFixed(1)}
                    </span>
                  )}
                  <span className="rounded border border-white/10 bg-black/20 px-1 py-0.5 text-zinc-300">
                    {meta ? formatAgentFinishedAt(meta.finishedAt) : '--:--:--'}
                  </span>
                </div>
              )}
            </div>
          )
        })}
      </div>
    </div>
  )
}

// ─── Deploy sub-step mini-progress ───────────────────────────────────────────

const DEPLOY_SUBSTEPS = [
  { n: 1, label: 'SPEC REPO',    detail: 'Push spec + docs to GitHub (private)' },
  { n: 2, label: 'APP REPO',     detail: 'Push generated app code to GitHub (public)' },
  { n: 3, label: 'VERCEL',       detail: 'Create Vercel project + trigger build' },
  { n: 4, label: 'BUILD POLL',   detail: 'Watching Vercel build — Next.js compiling…' },
  { n: 5, label: 'LIVE',         detail: 'App is live — production URL ready' },
]

function DeploySubGrid({ currentStep, result, localPreview }: { currentStep: number; result: DeployResult | null; localPreview?: LocalPreviewState | null }) {
  if (currentStep === 0) return null

  // Per-step outcome URLs — shown after each step completes
  const stepUrls: Record<number, string | null> = {
    1: result?.specRepoUrl  || null,
    2: result?.appRepoUrl   || null,
    3: result?.proposalUrl  || null,
    4: null,
    5: result?.proposalUrl  || null,
  }

  return (
    <div className="mt-3 space-y-1.5 bg-paper2/50 border border-border/50 rounded-xl p-3">
      {localPreview?.status === 'ready' && localPreview.url && (
        <div className="mb-3 rounded-xl border border-[#c8f23c]/40 bg-[#c8f23c]/10 p-3">
          <p className="mb-1.5 text-[9px] font-black uppercase tracking-widest text-[#c8f23c]">Tested local MVP URL</p>
          <a
            href={localPreview.url}
            target="_blank"
            rel="noopener noreferrer"
            className="flex w-full items-center justify-center rounded-lg bg-[#c8f23c] px-3 py-2 text-[11px] font-black text-black transition-all hover:bg-[#d4f74a]"
          >
            Open locally running app →
          </a>
          <p className="mt-1.5 break-all text-[9px] text-ink3">{localPreview.url}</p>
        </div>
      )}
      <p className="text-[9px] font-black font-mono tracking-widest text-ink3 uppercase mb-2.5">Deploy pipeline — 5 steps</p>
      {DEPLOY_SUBSTEPS.map(s => {
        const isDone   = currentStep > s.n
        const isActive = currentStep === s.n
        const url      = isDone ? stepUrls[s.n] : null
        return (
          <div
            key={s.n}
            className={`flex items-start gap-2.5 p-2.5 rounded-lg border transition-all ${
              isActive ? 'border-[#c8f23c]/60 bg-[#c8f23c]/5 shadow-[0_0_10px_rgba(200,242,60,0.15)]' :
              isDone   ? 'border-green-200/60 bg-paper' :
              'border-border/30 bg-paper2/40 opacity-40'
            }`}
          >
            {/* Step indicator */}
            <div className={`w-5 h-5 rounded-full flex-shrink-0 flex items-center justify-center text-[9px] font-black mt-0.5 ${
              isDone   ? 'bg-green-500 text-white' :
              isActive ? 'bg-[#c8f23c] text-black' :
              'bg-border/60 text-ink3'
            }`}>
              {isDone ? '✓' : s.n}
            </div>

            {/* Content */}
            <div className="flex-1 min-w-0">
              <div className="flex items-center gap-2">
                <p className={`text-[10px] font-black font-mono ${
                  isActive ? 'text-[#c8f23c]' : isDone ? 'text-ink' : 'text-ink3'
                }`}>{s.label}</p>
                {isActive && <span className="text-[8px] font-mono text-[#c8f23c]/80 animate-pulse">▸ running…</span>}
                {isDone && !url && <span className="text-[8px] font-mono text-green-600">complete</span>}
              </div>
              <p className="text-[9px] text-ink3 mt-0.5 leading-relaxed">{s.detail}</p>
              {url && (
                <a
                  href={url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="inline-flex items-center gap-1 text-[9px] font-mono text-[#c8f23c] hover:text-[#d4f74a] underline transition-colors mt-1 max-w-full truncate"
                >
                  {url.replace(/^https?:\/\//, '').slice(0, 52)}{url.replace(/^https?:\/\//, '').length > 52 ? '…' : ''} ↗
                </a>
              )}
            </div>
          </div>
        )
      })}

      {/* Live URL hero — shown only after deploy readiness is confirmed */}
      {currentStep >= 6 && result?.proposalUrl && result.deployReady && (
        <div className="mt-3 p-3 rounded-xl bg-[#c8f23c]/10 border border-[#c8f23c]/40">
          <p className="text-[9px] font-black font-mono tracking-widest text-[#5a6e00] uppercase mb-2">Live production URL</p>
          <a
            href={result.proposalUrl}
            target="_blank"
            rel="noopener noreferrer"
            className="flex items-center justify-center gap-2 w-full py-2.5 rounded-lg bg-[#c8f23c] text-black text-xs font-black hover:bg-[#d4f74a] transition-all shadow-[0_0_16px_rgba(200,242,60,0.3)] hover:scale-[1.01] active:scale-[0.99]"
          >
            Open Live App ↗
          </a>
        </div>
      )}

      {currentStep >= 4 && result?.proposalUrl && !result.deployReady && (
        <div className="mt-3 p-3 rounded-xl bg-amber-50 border border-amber-300">
          <p className="text-[9px] font-black font-mono tracking-widest text-amber-700 uppercase mb-1.5">Deployment submitted</p>
          <p className="text-[10px] text-amber-800 leading-relaxed">
            Vercel accepted the build. Public readiness is still being verified; the generated deployment URL may remain gated or unavailable until the build finishes and a public production alias is confirmed.
          </p>
        </div>
      )}

      {/* No-URL fallback — show manual deploy when tokens weren't configured */}
      {currentStep >= 6 && !result?.proposalUrl && result?.vercelImport && (
        <div className="mt-3 p-3 rounded-xl bg-paper border border-border/60">
          <p className="text-[9px] font-black font-mono tracking-widest text-ink3 uppercase mb-1.5">Deploy manually</p>
          <p className="text-[10px] text-ink3 mb-2">Vercel deploy wasn't triggered automatically — click below to import the repo and deploy in one click.</p>
          <a
            href={result.vercelImport}
            target="_blank"
            rel="noopener noreferrer"
            className="flex items-center justify-center gap-2 w-full py-2.5 rounded-lg bg-ink text-paper text-xs font-black hover:bg-ink/80 transition-all"
          >
            ▲ Import to Vercel →
          </a>
        </div>
      )}

      {/* No tokens at all */}
      {currentStep >= 6 && !result?.proposalUrl && !result?.vercelImport && !result?.appRepoUrl && (
        <div className="mt-3 p-3 rounded-xl bg-amber-50 border border-amber-300">
          <p className="text-[10px] font-bold text-amber-800 mb-1">Deploy tokens not configured</p>
          <p className="text-[9px] text-amber-700 mb-2">Your app code was generated but not deployed. Add GitHub and Vercel tokens to go live.</p>
          <button
            onClick={() => { window.location.href = '/shell?page=deploy' }}
            className="w-full py-2 rounded-lg bg-amber-500 text-white text-xs font-black hover:bg-amber-600 transition-all"
          >
            Configure Deploy Tokens →
          </button>
        </div>
      )}
    </div>
  )
}

// ─── Log viewer — virtualized ─────────────────────────────────────────────────
// Only the last LOG_WINDOW lines are mounted in the DOM. Earlier lines remain
// accessible via the "Show all" toggle and are never lost from the lines array.

const LOG_WINDOW = 80 // max lines rendered at once — prevents DOM bloat on long runs

function LogBox({ lines }: { lines: string[] }) {
  const ref  = useRef<HTMLDivElement>(null)
  const [collapsed,  setCollapsed]  = useState(false)
  const [showAll,    setShowAll]    = useState(false)

  const visible = (!showAll && lines.length > LOG_WINDOW)
    ? lines.slice(-LOG_WINDOW)
    : lines
  const hiddenCount = lines.length - visible.length

  useEffect(() => {
    if (ref.current && !collapsed) ref.current.scrollTop = ref.current.scrollHeight
  }, [lines, collapsed])

  if (lines.length === 0) return null
  return (
    <div className="overflow-hidden rounded-xl border border-white/10 bg-[#050607] shadow-[inset_0_1px_0_rgba(255,255,255,0.04)]">
      <button
        type="button"
        onClick={() => setCollapsed(c => !c)}
        className="w-full flex items-center gap-2 border-b border-white/10 bg-white/[0.025] px-3 py-2 text-left transition-colors hover:bg-white/[0.05]"
      >
        <span className="text-[9px] font-black font-mono tracking-widest text-ink3 uppercase flex-1">
          ◈ Pipeline Activity Log · {lines.length} events
        </span>
        <span className="text-[10px] text-ink3 font-mono">{collapsed ? '▼ show' : '▲ hide'}</span>
      </button>
      {!collapsed && (
        <div ref={ref} className="min-h-[180px] max-h-[360px] overflow-y-auto p-3 scrollbar-thin space-y-0.5">
          {hiddenCount > 0 && (
            <div className="flex items-center justify-between pb-1 border-b border-white/5 mb-1">
              <span className="text-[9px] font-mono text-zinc-500">{hiddenCount} earlier events hidden</span>
              <button
                type="button"
                onClick={() => setShowAll(true)}
                className="text-[9px] font-bold font-mono text-zinc-400 hover:text-zinc-200 underline transition-colors"
              >
                Show all
              </button>
            </div>
          )}
          {visible.map((l, i) => (
            <div key={showAll ? i : lines.length - LOG_WINDOW + i} className={`font-mono text-[10px] leading-relaxed ${
              l.includes('[✓]') ? 'text-green-600' :
              l.includes('[✗]') ? 'text-red-600'   :
              l.includes('[⚠]') ? 'text-amber-600' :
              'text-zinc-400'
            }`}>{l}</div>
          ))}
        </div>
      )}
    </div>
  )
}

// ─── Token config warning ─────────────────────────────────────────────────────

function TokenWarning({ ghOk, vercelOk }: { ghOk: boolean; vercelOk: boolean }) {
  if (ghOk && vercelOk) return null
  const missing = [!ghOk && 'GitHub', !vercelOk && 'Vercel'].filter(Boolean).join(' + ')
  return (
    <div className="rounded-xl border border-amber-300/35 bg-amber-300/10 overflow-hidden shadow-[inset_0_1px_0_rgba(255,255,255,0.04)]">
      <div className="flex items-start gap-3 px-4 py-3.5">
        <span className="text-amber-500 text-base flex-shrink-0 mt-0.5">⚠</span>
        <div className="flex-1 min-w-0">
          <p className="text-sm font-black text-amber-100">
            {missing} token{missing.includes('+') ? 's' : ''} not configured
          </p>
          <p className="text-[11px] text-amber-200/80 leading-relaxed mt-0.5">
            {!ghOk && 'Without a GitHub token, no repos will be created. '}
            {!vercelOk && 'Without a Vercel token, no live URL will be generated. '}
            Your app code will still be built — but deploy won't happen.
          </p>
        </div>
      </div>
      <div className="px-4 pb-4">
        <button
          onClick={() => { window.location.href = '/shell?page=deploy' }}
          className="w-full py-2.5 rounded-xl bg-amber-500 text-white text-sm font-black hover:bg-amber-600 transition-all shadow-sm"
        >
          Configure {missing} Token{missing.includes('+') ? 's' : ''} — Takes 2 min →
        </button>
      </div>
    </div>
  )
}

// ─── Confirm reset modal (replaces window.confirm) ───────────────────────────

function ConfirmResetModal({ onConfirm, onCancel }: { onConfirm: () => void; onCancel: () => void }) {
  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
      <div className="bg-paper border border-border rounded-2xl shadow-2xl w-full max-w-sm p-6 space-y-5 animate-fadein">
        <div>
          <p className="text-[9px] font-black font-mono tracking-widest text-amber-600 uppercase">Confirm reset</p>
          <h2 className="text-base font-black text-ink mt-1">Start a new pipeline?</h2>
          <p className="text-xs text-ink3 mt-1.5 leading-relaxed">This will clear the current build results and return to the brief input. Your GitHub repos and Vercel deployment will remain.</p>
        </div>
        <div className="flex gap-2">
          <button
            onClick={onCancel}
            className="flex-1 py-2.5 rounded-xl border border-border text-xs font-bold text-ink3 hover:text-ink hover:bg-paper2 transition-all"
          >
            Keep current
          </button>
          <button
            onClick={onConfirm}
            className="flex-1 py-2.5 rounded-xl bg-ink text-paper text-xs font-black hover:bg-ink/80 transition-all"
          >
            Yes, reset
          </button>
        </div>
      </div>
    </div>
  )
}

